  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mongodb\"\n  url      = env(\"DATABASE_URL\")\n}\n\n//\n// =================== USER ===================\n//\nmodel User {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name        String\n  email       String   @unique\n  password    String?\n  googleId    String?\n  phone       String?\n  role        Role     @default(USER)\n  deviceToken String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  orders    Order[]\n  addresses Address[]\n  carts     Cart[]\n}\n\nenum Role {\n  USER\n  ADMIN\n  DRIVER // shipper\n}\n\n//\n// =================== ADDRESS ===================\n//\nmodel Address {\n  id           String  @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId       String  @db.ObjectId\n  type         String\n  name         String\n  mobile       String\n  flatNo       String?\n  street       String?\n  landmark     String?\n  buildingName String?\n  pincode      String?\n  locality     String?\n\n  latitude  Float?\n  longitude Float?\n\n  user User @relation(fields: [userId], references: [id])\n}\n\n//\n// =================== RESTAURANT (1 nhà hàng nhưng chuẩn để mở rộng) ===================\n//\nmodel Restaurant {\n  id        String @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name      String\n  address   String\n  latitude  Float\n  longitude Float\n\n  openTime  String?\n  closeTime String?\n  isOpen    Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n//\n// =================== CATEGORY ===================\n//\nmodel Category {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name      String\n  imageUrl  String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  products Product[]\n}\n\n//\n// =================== PRODUCT ===================\n//\nmodel Product {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name        String\n  imageUrl    String?\n  description String?\n  price       Float\n  stock       Int\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  category   Category @relation(fields: [categoryId], references: [id])\n  categoryId String   @db.ObjectId\n}\n\n//\n// =================== DRIVER (SHIPPER) ===================\n//\nmodel Driver {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name        String\n  phone       String   @unique\n  avatar      String?\n  isOnline    Boolean  @default(false)\n  deviceToken String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  currentLat Float?\n  currentLng Float?\n\n  orders    Order[]\n  locations DriverLocation[]\n}\n\n//\n// ========== DRIVER LOCATION HISTORY (REALTIME TRACKING) ==========\n//\nmodel DriverLocation {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  driverId  String   @db.ObjectId\n  latitude  Float\n  longitude Float\n  timestamp DateTime @default(now())\n\n  driver Driver @relation(fields: [driverId], references: [id])\n}\n\n//\n// =================== ORDER ===================\n//\nmodel Order {\n  id          String      @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId      String      @db.ObjectId\n  items       Json[]\n  totalAmount Float\n  note        String?\n  status      OrderStatus @default(PENDING)\n\n  shippingDistance Float?\n  shippingFee      Float?\n  restaurantLat    Float?\n  restaurantLng    Float?\n\n  confirmedAt  DateTime?\n  preparedAt   DateTime?\n  readyAt      DateTime?\n  pickedUpAt   DateTime?\n  deliveringAt DateTime?\n  deliveredAt  DateTime?\n  canceledAt   DateTime?\n\n  paymentStatus PaymentStatus @default(PAYMENT_PENDING)\n\n  address Json\n  user    User @relation(fields: [userId], references: [id])\n\n  // shipper\n  driver   Driver? @relation(fields: [driverId], references: [id])\n  driverId String? @db.ObjectId\n\n  createdAt DateTime @default(now())\n\n  // PAYMENT — giữ nguyên theo schema của bạn\n  paymentMethod String  @default(\"ONLINE\")\n  paymentId     String?\n\n  zalopayOrderId                       String?\n  zalopayPaymentId                     String?\n  zalopayPaymentStatus                 String?\n  zalopayPaymentDate                   DateTime?\n  zalopayPaymentAmount                 Float?\n  zalopayPaymentCurrency               String?\n  zalopayPaymentGateway                String?\n  zalopayPaymentGatewayResponse        Json?\n  zalopayPaymentGatewayResponseMessage String?\n  zalopayPaymentGatewayResponseCode    String?\n\n  momopayOrderId                       String?\n  momopayPaymentId                     String?\n  momopayPaymentStatus                 String?\n  momopayPaymentDate                   DateTime?\n  momopayPaymentAmount                 Float?\n  momopayPaymentCurrency               String?\n  momopayPaymentGateway                String?\n  momopayPaymentGatewayResponse        Json?\n  momopayPaymentGatewayResponseMessage String?\n  momopayPaymentGatewayResponseCode    String?\n\n  logs     OrderLog[]\n  messages Message[]\n}\n\nenum OrderStatus {\n  PENDING\n  CONFIRMED\n  PREPARING\n  READY_FOR_PICKUP\n  PICKED_UP\n  DELIVERING\n  COMPLETED\n  CANCELED\n}\n\nenum PaymentStatus {\n  PAYMENT_PENDING\n  PAYMENT_SUCCESS\n  PAYMENT_FAILED\n  PAYMENT_REFUNDED\n}\n\n//\n// ========== ORDER LOG (LỊCH SỬ trạng thái giống Grab) ==========\n//\nmodel OrderLog {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  orderId   String   @db.ObjectId\n  oldStatus String?\n  newStatus String\n  message   String?\n  createdAt DateTime @default(now())\n\n  order Order @relation(fields: [orderId], references: [id])\n}\n\n//\n// =================== CART (tuỳ chọn) ===================\n//\nmodel Cart {\n  id     String @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId String @db.ObjectId\n  items  Json[]\n\n  user User @relation(fields: [userId], references: [id])\n}\n\n//\n// =================== VOUCHER ===================\n//\nmodel Voucher {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  code      String   @unique\n  discount  Float\n  minOrder  Float?\n  maxDeduct Float?\n  expiry    DateTime\n  createdAt DateTime @default(now())\n}\n\n//\n// =================== CHAT (KHÁCH ↔ SHIPPER) ===================\n//\nmodel Message {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  orderId   String   @db.ObjectId\n  senderId  String   @db.ObjectId\n  text      String\n  createdAt DateTime @default(now())\n\n  order Order @relation(fields: [orderId], references: [id])\n}\n",
